'use strict';
const nutritionModel=BloomNutrition;
let photoDraft={items:[],image:null,url:null,name:'',meal:'Lunch',notes:[]},cameraStream=null,photoRequest=null,photoEpoch=0,photoWorking=false,aiKey='',aiStatus=null;
function stopCamera(){if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;}
function resetPhotoMeal(){photoEpoch++;resetLocalReview();stopCamera();photoRequest?.abort();photoRequest=null;photoWorking=false;if(photoDraft.url)URL.revokeObjectURL(photoDraft.url);photoDraft={items:[],image:null,url:null,name:'',meal:'Lunch',notes:[]};aiKey='';aiStatus=null;}
const fmt=n=>(Math.round(n*10)/10).toLocaleString();
function nutritionGrid(values,known,count){return `<div class="nutrient-grid">${Object.entries(nutritionModel.nutrients).map(([key,[label,unit]])=>`<div><small>${label}</small><strong>${values[key]==null?'—':`${known&&known[key]<count?'≥ ':''}${fmt(values[key])}`} <span>${values[key]==null?'':unit}</span></strong></div>`).join('')}</div>`;}
function scanPage(){
  const totals=nutritionModel.totals(photoDraft.items);
  return `<div class="scan-layout"><section class="card photo-card"><div class="card-heading"><div><span class="card-kicker">A LITTLE LESS GUESSWORK</span><h2>Start with your plate</h2><small>AI assisted, always reviewed by you</small></div><span class="card-icon">${uiIcon('camera',23)}</span></div><div class="photo-stage">${photoDraft.url?`<img src="${photoDraft.url}" alt="Your selected meal photo">`:`<div class="photo-empty"><span>${uiIcon('camera',28)}</span><h3>What’s on your plate?</h3><p>Take a photo or choose one.<br>You’ll have the final say on every food.</p></div>`}<video id="camera-live" autoplay playsinline muted hidden></video></div><div class="photo-actions"><button class="secondary" data-photo="upload">${uiIcon('upload',15)} Choose photo</button><button class="secondary" data-photo="camera">${uiIcon('camera',15)} Use camera</button>${photoDraft.url?'<button class="text-button" data-photo="remove-photo">Remove photo</button>':''}</div><div id="camera-actions" hidden><button class="primary" data-photo="capture">Take photo</button> <button class="text-button" data-photo="camera-stop">Cancel camera</button></div>${localModelPanel()}<div class="ai-explainer"><strong>${uiIcon('spark',17)} Photo intelligence · OpenAI</strong><p>Only the selected photo is sent to OpenAI when you choose Analyze. Your account and journal are not sent. API usage may be billed.</p><button class="text-button" data-photo="connect">${aiKey?'Change AI connection':'Connect AI'}</button><button class="primary analyze-button" data-photo="analyze" ${!photoDraft.image||photoWorking?'disabled':''}>${photoWorking?'Analyzing photo…':'Analyze photo with AI ↗'}</button>${photoWorking?'<button class="text-button" data-photo="cancel-analysis">Cancel analysis</button>':''}</div><p class="notice">Prefer completely local? Use a connected local model, or add food below. No image is uploaded unless you ask. Photos are not stored in your journal or backups.</p></section><section class="card meal-review"><div class="card-heading"><div><span class="card-kicker">YOUR PLATE, YOUR CALL</span><h2>Make it your meal</h2><small>Add anything missed. Adjust every portion.</small></div><span class="step-label">REVIEW BEFORE LOGGING</span></div>${photoDraft.notes.length?`<div class="photo-notes" role="status">${photoDraft.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div>`:''}<div class="review-items">${photoDraft.items.length?photoDraft.items.map((item,i)=>`<div class="review-item"><div><strong>${esc(item.name)}</strong><small>${esc(item.source)} · ${fmt(item.per100.calories)} kcal / 100g</small></div><label>Portion (g)<input data-portion="${i}" type="number" min="0.1" max="5000" step="0.1" value="${item.grams}" aria-label="Portion for ${esc(item.name)} in grams" ${photoWorking?'disabled':''}></label><span>${fmt(item.per100.calories*item.grams/100)}<small>kcal</small></span><button class="text-button" data-edit-item="${i}" ${photoWorking?'disabled':''}>Edit</button><button class="remove" data-remove-item="${i}" aria-label="Remove ${esc(item.name)}" ${photoWorking?'disabled':''}>✕</button></div>`).join(''):'<div class="empty"><strong>A fresh plate, ready to fill.</strong>Analyze a photo or add your first food manually.</div>'}</div><button class="secondary add-ingredient" data-photo="add" ${photoWorking?'disabled':''}>＋ Add missing food or ingredient</button><div class="meal-entry-fields"><label>Meal name<input id="scan-name" maxlength="90" placeholder="e.g. Lunch bowl" value="${esc(photoDraft.name)}"></label><label>Meal<select id="scan-type">${['Breakfast','Lunch','Dinner','Snack'].map(m=>`<option ${photoDraft.meal===m?'selected':''}>${m}</option>`).join('')}</select></label></div><div class="review-total"><small>ESTIMATED MEAL TOTAL</small><strong>${fmt(totals.values.calories||0)} <span>kcal</span></strong><p>${fmt(totals.values.protein||0)}g protein · ${fmt(totals.values.carbs||0)}g carbs · ${fmt(totals.values.fat||0)}g fat</p></div>${photoDraft.items.length?`<details class="nutrition-details"><summary>Vitamins, minerals &amp; more</summary>${nutritionGrid(totals.values,totals.known,photoDraft.items.length)}<p class="notice">— means unknown. ≥ shows only the known amount when some ingredients lack data. Micronutrients from AI are rough estimates, not measured values.</p></details>`:''}<p class="notice">Photos cannot measure portion weight, oil, sauces or hidden ingredients. Check all items and quantities before logging. These estimates do not determine your overall health.</p><button class="primary log-reviewed" data-photo="log" ${!photoDraft.items.length||photoWorking?'disabled':''}>✓ Log meal as consumed · ${date}</button></section></div><input id="meal-photo-file" type="file" accept="image/jpeg,image/png,image/webp" hidden>`;
}
function renderScan(){if(session&&page==='scan'){render();bindScan();}}
function bindScan(){
  if(!session||page!=='scan')return;
  bindLocalModel();
  $('#scan-name').oninput=e=>{photoDraft.name=e.target.value;};$('#scan-type').onchange=e=>{photoDraft.meal=e.target.value;};
  $('#meal-photo-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||photoWorking)return;await loadPhoto(file);};
  document.querySelectorAll('[data-portion]').forEach(input=>{input.onchange=()=>{if(photoWorking)return;if(!input.reportValidity()){input.value=photoDraft.items[Number(input.dataset.portion)].grams;return;}photoDraft.items[Number(input.dataset.portion)].grams=Number(input.value);renderScan();};});
}
async function setPhotoFromCanvas(canvas){
  const target=photoDraft,epoch=photoEpoch;
  const image=canvas.toDataURL('image/jpeg',.85);if(image.length>2500000)throw new Error('The resized photo is still too large. Try a simpler or smaller image.');
  if(photoDraft.url)URL.revokeObjectURL(photoDraft.url);resetLocalReview();photoDraft.image=image;
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(epoch!==photoEpoch||target!==photoDraft)return;photoDraft.url=URL.createObjectURL(blob);photoDraft.notes=[];
}
async function loadPhoto(file){
  const epoch=photoEpoch;
  try{if(file.size>15*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Choose a JPEG, PNG or WebP photo under 15 MB.');
    const bitmap=await createImageBitmap(file);if(epoch!==photoEpoch){bitmap.close();return;}
    const scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();stopCamera();await setPhotoFromCanvas(canvas);if(epoch!==photoEpoch)return;renderScan();
  }catch(error){toast(error.message||'This photo could not be opened. Choose another image.');}
}
async function startCamera(){
  if(!navigator.mediaDevices?.getUserMedia){toast('Camera access is unavailable. Choose a photo instead.');return;}
  const epoch=photoEpoch;
  try{stopCamera();const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(epoch!==photoEpoch||page!=='scan'){stream.getTracks().forEach(t=>t.stop());return;}cameraStream=stream;const video=$('#camera-live');video.hidden=false;video.srcObject=stream;await video.play();$('#camera-actions').hidden=false;}
  catch{stopCamera();toast('Could not use the camera. Allow camera access in your browser, or choose a photo.');}
}
function connectAI(){
  $('#dialog-title').textContent='Connect photo AI';
  $('#entry-form').innerHTML='<p class="form-help">Use your OpenAI API key for photo analysis. It stays in memory until you lock or refresh Bloom and is not included in backups. A ChatGPT subscription does not configure this connection.</p><label>OpenAI API key<input id="ai-key" name="apiKey" type="password" autocomplete="off" maxlength="512" placeholder="Enter your API key" required></label><p class="form-help">The key is used only for requests to OpenAI through Bloom’s local server. API usage may be billed to your OpenAI account.</p><button class="primary" type="submit">Use key for this session</button>';
  $('#entry-form').onsubmit=e=>{e.preventDefault();if(!$('#entry-form').reportValidity())return;aiKey=$('#ai-key').value.trim();$('#entry-form').reset();$('#modal').close();toast('AI key set for this session. Analyze a photo to use it.');renderScan();};$('#modal').showModal();
}
async function analyzePhoto(){
  if(photoWorking||!photoDraft.image||!session)return;
  if(photoDraft.items.length){toast('Clear the current food items before analyzing another photo. This keeps your reviewed foods from being replaced.');return;}
  photoWorking=true;const epoch=photoEpoch,accountId=session.record.id;photoRequest=new AbortController();const controller=photoRequest;const timeout=setTimeout(()=>controller.abort(),100000);renderScan();
  try{
    const response=await fetch(`${window.BLOOM_API_BASE}/api/ai/analyze`,{method:'POST',headers:{'Content-Type':'application/json','X-Bloom-Request':'1',...(aiKey?{'X-Bloom-AI-Key':aiKey}:{})},body:JSON.stringify({image:photoDraft.image,consent:true}),signal:controller.signal});
    let result;try{result=await response.json();}catch{throw new Error('Start the updated app using Open Bloom.cmd to enable the AI connection.');}
    if(!response.ok)throw new Error(result.error||'Could not analyze the photo. Please try again.');
    if(epoch!==photoEpoch||session?.record.id!==accountId)return;
    if(!Array.isArray(result.items)||result.items.length>40)throw new Error('The AI result was incomplete. Nothing was logged.');
    photoDraft.items=result.items.map(nutritionModel.cleanItem);photoDraft.notes=(result.notes||[]).filter(n=>typeof n==='string').slice(0,8);
    if(!photoDraft.items.length)photoDraft.notes=['No clear food was identified. Try a clearer photo or add the foods manually.'];else photoDraft.notes.unshift('AI suggestions only. Review each food, portion and nutrition value before logging.');
  }catch(error){if(epoch===photoEpoch)toast(error.name==='AbortError'?'Analysis stopped. You can retry or enter foods manually.':error.message);}
  finally{clearTimeout(timeout);if(epoch===photoEpoch){photoWorking=false;photoRequest=null;renderScan();}}
}
function editIngredient(index=null,preset=null){
  if(photoWorking)return;const existing=index==null?preset:photoDraft.items[index];
  $('#dialog-title').textContent=index!=null?'Edit food & portion':'Add a food or ingredient';
  $('#entry-form').innerHTML=`<label>Food name<input name="foodName" id="ingredient-name" list="starter-foods" maxlength="90" placeholder="Search a starter food or enter your own" value="${esc(existing?.name||'')}" required></label><datalist id="starter-foods">${nutritionModel.catalog.map(f=>`<option value="${esc(f.name)}"></option>`).join('')}</datalist><label>Portion eaten (grams)<input name="grams" type="number" min="0.1" max="5000" step="0.1" value="${preset?'':existing?.grams||100}" required></label><p class="form-help">Nutrition values below are <strong>per 100 grams</strong>. Starter foods use generic estimates. For recipes or packaged food, use your recipe or label values. Blank micronutrients stay unknown.</p><div class="form-row">${Object.entries(nutritionModel.nutrients).slice(0,4).map(([key,[label,unit,max]])=>`<label>${label} (${unit})<input name="${key}" type="number" min="0" max="${max}" step="any" value="${existing?.per100[key]??''}" required></label>`).join('')}</div><details><summary>Fiber, sugar, vitamins &amp; minerals (optional)</summary><div class="form-row optional-nutrients">${Object.entries(nutritionModel.nutrients).slice(4).map(([key,[label,unit,max]])=>`<label>${label} (${unit})<input name="${key}" type="number" min="0" max="${max}" step="any" value="${existing?.per100[key]??''}"></label>`).join('')}</div></details><p class="form-help" id="ingredient-error" role="alert"></p><button class="primary" type="submit">${index!=null?'Update food':'Add food'}</button>`;
  let source=existing?.source||'Food label / manual';const form=$('#entry-form');
  $('#ingredient-name').oninput=e=>{const match=nutritionModel.catalog.find(f=>f.name.toLowerCase()===e.target.value.trim().toLowerCase());if(match){for(const key of Object.keys(nutritionModel.nutrients))form.elements[key].value=match.per100[key]??'';source='Starter estimate';}};
  for(const key of Object.keys(nutritionModel.nutrients))form.elements[key].oninput=()=>{source='Food label / manual';};
  form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;try{if(index==null&&photoDraft.items.length>=40)throw new Error('Use up to 40 items per meal.');const values=Object.fromEntries(new FormData(form)),per100={};for(const key of Object.keys(nutritionModel.nutrients))per100[key]=values[key]===''?null:Number(values[key]);const item=nutritionModel.cleanItem({name:values.foodName,grams:Number(values.grams),per100,source,...(existing?.recognition?{recognition:existing.recognition}:{})});if(index==null)photoDraft.items.push(item);else photoDraft.items[index]=item;$('#modal').close();renderScan();}catch(error){$('#ingredient-error').textContent=error.message;}};
  $('#modal').showModal();
}
function dailyNutrients(){const meals=day().meals,values={},known={};for(const key of Object.keys(nutritionModel.nutrients)){const matches=meals.filter(m=>m.nutrients?.[key]!=null);values[key]=matches.length?matches.reduce((n,m)=>n+m.nutrients[key],0):null;known[key]=matches.filter(m=>!m.items||m.nutrientCoverage?.[key]===m.items.length).length;}
  const keys=['fiber','sugar','sodium','calcium','iron','potassium','vitaminA','vitaminC','vitaminD','b12'];return `<section class="card nutrient-card"><div class="card-heading"><div><span class="card-kicker">BEYOND THE MACROS</span><h2>Nutrients you’ve logged</h2><small>Known contributions from your meal entries</small></div></div><div class="nutrient-grid">${keys.map(key=>{const [label,unit]=nutritionModel.nutrients[key];return `<div><small>${label}</small><strong>${values[key]==null?'—':`${known[key]<meals.length?'≥ ':''}${fmt(values[key])}`} <span>${values[key]==null?'':unit}</span></strong></div>`;}).join('')}</div><p class="notice">— means not tracked. ≥ means some meals or ingredients have missing values. AI and starter estimates vary; these totals are not a complete assessment of your health.</p></section>`;}
document.addEventListener('click',async e=>{
  if(!session||busy)return;const control=e.target.closest('[data-photo],[data-edit-item],[data-remove-item]');if(!control)return;
  if(control.dataset.editItem!=null){editIngredient(Number(control.dataset.editItem));return;}
  if(control.dataset.removeItem!=null){if(!photoWorking){photoDraft.items.splice(Number(control.dataset.removeItem),1);renderScan();}return;}
  const action=control.dataset.photo;
  if(action==='connect')connectAI();else if(action==='add')editIngredient();else if(action==='upload'){if(!photoWorking)$('#meal-photo-file').click();}else if(action==='camera'){if(!photoWorking)await startCamera();}else if(action==='camera-stop'){stopCamera();$('#camera-live').hidden=true;$('#camera-actions').hidden=true;}else if(action==='cancel-analysis')photoRequest?.abort();else if(action==='analyze')await analyzePhoto();
  else if(action==='remove-photo'&&!photoWorking){stopCamera();if(photoDraft.url)URL.revokeObjectURL(photoDraft.url);photoDraft.url=null;photoDraft.image=null;resetLocalReview();renderScan();}
  else if(action==='capture'&&cameraStream){try{const video=$('#camera-live'),canvas=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(video.videoWidth,video.videoHeight));canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);if(!canvas.width||!canvas.height)throw new Error('The camera is not ready yet. Try again.');canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);stopCamera();await setPhotoFromCanvas(canvas);renderScan();}catch(error){toast(error.message);}}
  else if(action==='log'&&!photoWorking){try{const entry=nutritionModel.meal(photoDraft.items,photoDraft.meal,photoDraft.name,crypto.randomUUID());writableDay().meals.push(entry);const saved=await save();resetPhotoMeal();location.hash='#food';render();if(saved)toast('Meal logged as consumed. Your daily totals are updated.');}catch(error){toast(error.message);}}
});
document.addEventListener('click',e=>{
  const control=e.target.closest('[data-meal-details]');if(!control||!session||busy)return;
  const entry=day().meals.find(m=>m.id===control.dataset.mealDetails);if(!entry?.items)return;
  const totals=nutritionModel.totals(entry.items);$('#dialog-title').textContent=entry.name;
  $('#entry-form').innerHTML=`<p class="form-help">${esc(entry.meal)} · Logged as consumed · ${date}</p>${entry.items.map(i=>`<div class="meal"><div class="meal-info"><strong>${esc(i.name)}</strong><p>${i.grams}g · ${esc(i.source)}</p></div><span>${fmt(i.per100.calories*i.grams/100)} kcal</span></div>`).join('')}${nutritionGrid(totals.values,totals.known,entry.items.length)}<p class="notice">Estimates for the portions logged. Unknown nutrients are not counted as zero.</p><button type="button" class="primary" id="close-meal-details">Done</button>`;
  $('#close-meal-details').onclick=()=>$('#modal').close();$('#modal').showModal();
});
